from 写入第二遍 import add
add('14_003',1.5,'16:9，青正面脸部特写居画面中央，半垂眼、压低的眉与绷紧嘴角同框，两边长发竖落；固定机位，竖向细线穿过头侧。','青踩稳后下颌微收，眼睑压得更低，眉尖向内锁紧；她把一口气压在齿间，肩膀下沉，嘴角绷成短短波折。短喝从闭齿间推出来时，脸颊轻绷，竖直发束先向下拉紧，下一瞬腰胯已把力量顶向上方。','两侧发隙之外为深蓝灰竖向图形底，冷白细线由下向上掠过，底部无近处建筑。','云天冷白柔光仍在脸上，眉眼下方压深一层冷灰，竖线只作速度图形。','压紧的一次短呼气，护腕衣料轻绷，石面下低短回响。',ja=['ふううっ！！！！'],tone='青压住气息发力，短喝先紧后放，收在起腿的瞬间。',kind='mixed',phase='preparation',node={'叙事阶段':'青踩实后蓄力起腿'},meaning='半垂眼、紧眉与咬紧的波折嘴角保留，短喝接全身上踢。',motion='脸保持对敌方向，身体向下压紧后转向上方发力。',ground='支撑脚仍着地承重，腰胯开始上提。',characters=['青'])
add('15_001',3,'16:9，先以青的低机位全景起幅，头与双腿完整；镜头随上踢方向仰摇并迅速拉远，落幅青占下方中央，竖直踢腿通向中层，武士黑色小身影高悬上方云隙，白色长弧沿画面左侧展开。','青从压紧的支撑腿猛然蹬起，腰胯上送，一腿沿身体前侧直甩到头顶，另一腿屈收；她双拳收紧、闭眼咬牙，起腿短喝一口气冲出。武士被这一踢送往镜头上方，体形随仰摇迅速缩成云天中的小黑影；青的竖直踢腿到顶后稳住极短一拍，银白马尾向后回卷，大白弧从脚下越过身侧后向上拔长。','上方蓝灰云层层叠，白色速度粒在云隙稀疏散开，最下缘一小带灰绿石铺地面很快退出画幅。','正上方冷白漫射统一，青衣色、银发与白色袜靴保持分层；长白弧是短促冲击图形，人物光向稳定。','支撑脚蹬石短轰接一记沉实踢击，长破风骤然向高处拔起，衣摆与发尾急响。',ja=['てやっ！！！'],tone='青在腿甩直到顶之前短促喝出，重音随爆发上送，干脆收净。',kind='mixed',phase='result',node={'叙事阶段':'上踢将武士送上高空','青.位置':'近平台上方收腿前','武士.位置':'向高空急升'},meaning='保留竖直上踢腿、另一屈腿、闭眼握拳与高处武士小身影，竖格通过仰摇拉远展开高度。',motion='青起腿从下向上；武士沿上踢方向离镜，再在上方远层显小；摄影机仰摇到两者同框的落幅。',ground='青由支撑足蹬地转短暂腾空，踢后另一腿屈收；武士完全离地上升。',characters=['青','鬼头武士'])
add('16_001',3.5,'16:9，悬空城镇平台的极远全景，主岩台横在画面下方，左侧高处岩台与斜索形成纵深；机位固定，细亮轨迹由下方城镇中央直上画面上部亮点。','极细的竖直亮迹从主平台中央拔向高处，顶端小亮点继续上升一小段，拖尾随距离越拉越细；两片云在轨迹两侧缓慢分开，细白点从亮迹旁向外散。下方屋顶群与连台斜索几乎静止，让上下高度清楚地留在一眼里。','主平台为深灰褐断岩与灰米城镇、蓝灰屋顶；左侧另一段高岩台伸入，深褐斜索连向主平台。天空深蓝灰云层层叠，细白粒散在高处云隙。','上方开阔云天冷白光，岩体下侧深冷灰；顶端微小亮点只强化远处速度位置，平台明暗保持日间阴云层次。','高处细长破风拉远，平台附近只留一层很低的轰响余声，风声渐宽。',phase='result',node={'叙事阶段':'旁观极远景交代被击飞高度','武士.位置':'悬空城镇上方极高处'},meaning='极远悬空平台、斜索和竖直轨迹保留，速度表现沿漫画处理，时间仍承接同一白日战斗。',motion='轨迹自下往上，平台和索不动，机位不追近高空人物。',ground='武士远在高空，青暂在平台侧画外，镜头不冒报新的接触。',characters=[])
